
import uuid
from datetime import datetime

from app.extensions import db


class CustomerOrder(db.Model):
    """
    Represents an order submitted through the public BrightSpark website.

    Submitting an order does not record a sale, accept a payment,
    or deduct inventory. Staff must review the order separately.
    """

    __tablename__ = "customer_orders"

    id = db.Column(
        db.String(36),
        primary_key=True,
        default=lambda: str(uuid.uuid4())
    )

    # Customer-facing reference, generated by the backend.
    order_reference = db.Column(
        db.String(30),
        nullable=False,
        unique=True,
        index=True
    )

    # The branch responsible for fulfilling this order.
    branch_id = db.Column(
        db.String(36),
        db.ForeignKey("branches.id"),
        nullable=False,
        index=True
    )

    customer_name = db.Column(
        db.String(150),
        nullable=False
    )

    customer_phone = db.Column(
        db.String(30),
        nullable=False
    )

    customer_email = db.Column(
        db.String(255),
        nullable=True
    )

    # PICKUP or DELIVERY.
    fulfilment_method = db.Column(
        db.String(20),
        nullable=False
    )

    delivery_address = db.Column(
        db.Text,
        nullable=True
    )

    customer_notes = db.Column(
        db.Text,
        nullable=True
    )

    # Total calculated by the backend when the order is submitted.
    total_amount = db.Column(
        db.Numeric(12, 2),
        nullable=False,
        default=0
    )

    # PENDING, CONFIRMED, REJECTED, or COMPLETED.
    # COMPLETED must only be used when the business's fulfilment
    # and sale-recording process has actually been completed.
    status = db.Column(
        db.String(30),
        nullable=False,
        default="PENDING",
        index=True
    )

    # Optional staff member who last reviewed/updated the order.
    reviewed_by = db.Column(
        db.String(36),
        db.ForeignKey("users.id"),
        nullable=True
    )

    reviewed_at = db.Column(
        db.DateTime,
        nullable=True
    )

    created_at = db.Column(
        db.DateTime,
        default=datetime.utcnow,
        nullable=False,
        index=True
    )

    updated_at = db.Column(
        db.DateTime,
        default=datetime.utcnow,
        onupdate=datetime.utcnow,
        nullable=False
    )

    branch = db.relationship(
        "Branch",
        backref=db.backref("customer_orders", lazy=True)
    )

    reviewer = db.relationship(
        "User",
        foreign_keys=[reviewed_by]
    )

    items = db.relationship(
        "CustomerOrderItem",
        back_populates="order",
        cascade="all, delete-orphan",
        lazy=True
    )

    def __repr__(self):
        return f"<CustomerOrder {self.order_reference}>"


class CustomerOrderItem(db.Model):
    """
    A product line belonging to a customer order.

    Stores a snapshot of the unit price displayed/calculated when
    the order was placed. It does not reserve or consume inventory.
    """

    __tablename__ = "customer_order_items"

    id = db.Column(
        db.String(36),
        primary_key=True,
        default=lambda: str(uuid.uuid4())
    )

    order_id = db.Column(
        db.String(36),
        db.ForeignKey("customer_orders.id"),
        nullable=False,
        index=True
    )

    product_id = db.Column(
        db.String(36),
        db.ForeignKey("products.id"),
        nullable=False
    )

    product_name = db.Column(
        db.String(200),
        nullable=False
    )

    product_sku = db.Column(
        db.String(100),
        nullable=False
    )

    quantity = db.Column(
        db.Numeric(12, 3),
        nullable=False
    )

    unit = db.Column(
        db.String(50),
        nullable=False
    )

    unit_price = db.Column(
        db.Numeric(12, 2),
        nullable=False
    )

    line_total = db.Column(
        db.Numeric(12, 2),
        nullable=False
    )

    order = db.relationship(
        "CustomerOrder",
        back_populates="items"
    )

    product = db.relationship(
        "Product",
        backref=db.backref("customer_order_items", lazy=True)
    )

    def __repr__(self):
        return f"<CustomerOrderItem {self.product_name}>"
